export class VectorService {
    #datasetService;
    #collectionName;
    #baseUrl;
    #collectionId;
    #initialized;
    #ready;

    constructor({
        datasetService,
        collectionName = 'ecommerce_product_vectors',
        baseUrl = 'http://localhost:8000'
    } = {}) {
        this.#datasetService = datasetService;
        this.#collectionName = collectionName;
        this.#baseUrl = baseUrl;
        this.#collectionId = null;
        this.#initialized = false;
        this.#ready = false;
    }

    async initialize() {
        if (this.#initialized) {
            return this.#ready;
        }

        this.#initialized = true;

        try {
            const response = await fetch(
                `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections`
            );
            if (!response.ok) throw new Error(`Chroma returned ${response.status}`);

            const collections = await response.json();
            const collection = collections.find(item => item.name === this.#collectionName);
            this.#collectionId = collection?.id || null;
            this.#ready = Boolean(this.#collectionId && collection.dimension);
        } catch (error) {
            console.warn('[VectorService] Chroma vector index is unavailable; falling back to the current recommendation flow.', error);
            this.#ready = false;
        }

        return this.#ready;
    }

    async ensureIndexed() {
        await this.initialize();
        return this.#ready;
    }

    async getCandidateProductsForUser(user) {
        await this.initialize();

        if (!this.#ready || !this.#collectionId || !this.#datasetService) {
            return null;
        }

        const { products } = await this.#datasetService.getDataset();
        const purchasedIds = new Set((user?.purchases || []).map(purchase => String(purchase.id)));
        const response = await fetch(
            `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections/${this.#collectionId}/query`,
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    query_embeddings: [this.#toUserVector(user)],
                    n_results: Math.min(100, products.length),
                    include: ['metadatas']
                })
            }
        );
        if (!response.ok) throw new Error(`Chroma query returned ${response.status}`);

        const result = await response.json();
        const productIds = result.metadatas?.[0]
            ?.map(metadata => metadata?.productId)
            .filter(Boolean) || [];
        const productsById = new Map(products.map(product => [String(product.id), product]));

        return productIds
            .map(productId => productsById.get(String(productId)))
            .filter(product => product && !purchasedIds.has(String(product.id)));
    }

    #toUserVector(user = {}) {
        const values = [
            Number(user.age || 0),
            Number(user.Session_Duration_Min || 0),
            Number(user.Pages_Viewed || 0),
            Number(user.Previous_Purchases || 0),
            Number(user.User_Rating || 0),
            Number(user.purchases?.length || 0),
            Number(user.Session_Duration_Min || 0) + Number(user.Pages_Viewed || 0),
            Number(user.User_Rating || 0) + Number(user.purchases?.length || 0)
        ];

        return values.map(value => Number.isFinite(value) ? value : 0);
    }
}

export class ModelController {
    #modelView;
    #userService;
    #datasetService;
    #vectorService;
    #events;
    #currentUser = null;
    #alreadyTrained = false;
    constructor({
        modelView,
        userService,
        datasetService,
        vectorService,
        events,
    }) {
        this.#modelView = modelView;
        this.#userService = userService;
        this.#datasetService = datasetService;
        this.#vectorService = vectorService;
        this.#events = events;

        this.init();
    }

    static init(deps) {
        return new ModelController(deps);
    }

    async init() {
        this.setupCallbacks();
    }

    setupCallbacks() {
        this.#modelView.registerTrainModelCallback(this.handleTrainModel.bind(this));
        this.#modelView.registerRunRecommendationCallback(this.handleRunRecommendation.bind(this));

        this.#events.onUserSelected((user) => {
            this.#currentUser = user;
            if (!this.#alreadyTrained) return
            this.#modelView.enableRecommendButton();
        });

        this.#events.onTrainingComplete(({ metrics } = {}) => {
            this.#alreadyTrained = true;
            if (!this.#currentUser) return
            this.#modelView.enableRecommendButton();
            this.dispatchRecommendation(this.#currentUser);
            if (metrics) console.log('Model test metrics:', metrics);
        })

        this.#events.onUsersUpdated(
            async (...data) => {
                return this.refreshUsersPurchaseData(...data);
            }
        );
        this.#events.onProgressUpdate(
            (progress) => {
                this.handleTrainingProgressUpdate(progress);
            }
        );

    }


    async handleTrainModel() {
        const dataset = await this.#datasetService.getDataset();
        this.#events.dispatchTrainModel(dataset);
    }

    handleTrainingProgressUpdate(progress) {
        this.#modelView.updateTrainingProgress(progress);
    }
    async handleRunRecommendation() {
        const currentUser = this.#currentUser;
        const updatedUser = await this.#userService.getUserById(currentUser.id);
        await this.dispatchRecommendation(updatedUser);
    }

    async dispatchRecommendation(user) {
        let candidateProducts = null;
        try {
            candidateProducts = await this.#vectorService?.getCandidateProductsForUser(user);
        } catch (error) {
            console.warn('Unable to retrieve Chroma recommendation candidates; using the full catalog.', error);
        }
        this.#events.dispatchRecommend({ user, candidateProducts });
    }

    async refreshUsersPurchaseData({ users }) {
        this.#modelView.renderAllUsersPurchases(users);
    }
}

