{
    "name": "ecommerce-recomendations-with-ml",
    "version": "1.0.0",
    "description": "An e-commerce recommendation system with TensorFlow.js",
    "main": "index.js",
    "type": "module",
    "scripts": {
        "start": "node scripts/dev-server.mjs",
        "test": "echo \"Error: no test specified\" && exit 1",
        "vectorize": "node scripts/vectorize.mjs",
        "clear-vectors": "node scripts/clear-vectors.mjs"
    },
    "keywords": [
        "ecommerce",
        "tensorflow",
        "recommendation",
        "javascript"
    ],
    "author": "",
    "license": "ISC",
    "devDependencies": {
        "browser-sync": "^3.0.4"
    },
    "dependencies": {
        "chromadb": "^3.5.0"
    }
}

const NUMERIC_FIELDS = [
    'User_Age',
    'Session_Duration_Min',
    'Pages_Viewed',
    'Previous_Purchases',
    'User_Rating',
    'Product_Price',
    'Discount_Applied',
    'Graph_Similarity_Score',
    'Federated_Cluster_ID',
    'Local_Model_Accuracy',
    'Global_Model_Weight',
    'Personalization_Factor',
    'Purchase_Probability',
    'Recommended'
];

const mode = values => {
    const counts = new Map();
    values.forEach(value => counts.set(value, (counts.get(value) || 0) + 1));
    return [...counts.entries()].sort((first, second) => second[1] - first[1])[0]?.[0] || '';
};

const mean = values => values.reduce((sum, value) => sum + value, 0) / (values.length || 1);

export class ChromaDatasetService {
    #baseUrl;
    #interactionCollectionName;
    #datasetPromise;

    constructor({
        baseUrl = '/chroma',
        interactionCollectionName = 'ecommerce_interaction_vectors'
    } = {}) {
        this.#baseUrl = baseUrl;
        this.#interactionCollectionName = interactionCollectionName;
    }

    async getDataset() {
        if (!this.#datasetPromise) {
            this.#datasetPromise = this.#loadDataset();
        }
        return this.#datasetPromise;
    }

    async #loadDataset() {
        const collectionResponse = await fetch(
            `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections`
        );
        if (!collectionResponse.ok) {
            throw new Error(`Unable to access Chroma collections (${collectionResponse.status})`);
        }

        const collections = await collectionResponse.json();
        const collection = collections.find(item => item.name === this.#interactionCollectionName);
        if (!collection?.id || !collection.dimension) {
            throw new Error(`Chroma collection '${this.#interactionCollectionName}' is missing or empty`);
        }

        const response = await fetch(
            `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections/${collection.id}/get`,
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ include: ['documents'] })
            }
        );
        if (!response.ok) {
            throw new Error(`Unable to read Chroma interactions (${response.status})`);
        }

        const result = await response.json();
        const interactions = (result.documents || []).map((document, index) => this.#normalizeRow(document, index));
        if (!interactions.length) {
            throw new Error(`Chroma collection '${this.#interactionCollectionName}' contains no interactions`);
        }

        const products = this.#createProducts(interactions);
        const productsById = new Map(products.map(product => [product.id, product]));
        const users = this.#createUsers(interactions, productsById);
        return { interactions, products, users };
    }

    #normalizeRow(document, index) {
        let row;
        try {
            row = JSON.parse(document);
        } catch (error) {
            throw new Error(`Invalid Chroma interaction document ${index + 1}: ${error.message}`);
        }

        const normalized = Object.fromEntries(
            Object.entries(row).map(([key, value]) => [key, typeof value === 'string' ? value.trim() : value])
        );
        NUMERIC_FIELDS.forEach(field => {
            normalized[field] = Number(normalized[field]);
            if (!Number.isFinite(normalized[field])) {
                throw new Error(`Invalid ${field} in Chroma interaction ${index + 1}`);
            }
        });
        if (!normalized.User_ID || !normalized.Product_ID) {
            throw new Error(`Missing user or product ID in Chroma interaction ${index + 1}`);
        }
        return normalized;
    }

    #createProducts(interactions) {
        const grouped = new Map();
        interactions.forEach(row => {
            if (!grouped.has(row.Product_ID)) grouped.set(row.Product_ID, []);
            grouped.get(row.Product_ID).push(row);
        });

        return [...grouped.entries()].map(([id, rows]) => ({
            id,
            productId: id,
            name: `Product ${id}`,
            category: mode(rows.map(row => row.Category)),
            brand: mode(rows.map(row => row.Brand)),
            price: mean(rows.map(row => row.Product_Price)),
            graphSimilarityScore: mean(rows.map(row => row.Graph_Similarity_Score)),
            federatedClusterId: mode(rows.map(row => row.Federated_Cluster_ID)),
            localModelAccuracy: mean(rows.map(row => row.Local_Model_Accuracy)),
            globalModelWeight: mean(rows.map(row => row.Global_Model_Weight)),
            personalizationFactor: mean(rows.map(row => row.Personalization_Factor)),
            purchaseProbability: mean(rows.map(row => row.Purchase_Probability)),
            recommendationRate: mean(rows.map(row => row.Recommended))
        }));
    }

    #createUsers(interactions, productsById) {
        const grouped = new Map();
        interactions.forEach(row => {
            if (!grouped.has(row.User_ID)) grouped.set(row.User_ID, []);
            grouped.get(row.User_ID).push(row);
        });

        return [...grouped.entries()].map(([id, rows]) => {
            const positiveProductIds = [...new Set(
                rows.filter(row => row.Recommended === 1).map(row => row.Product_ID)
            )];
            return {
                id,
                name: `User ${id}`,
                age: Math.round(mean(rows.map(row => row.User_Age))),
                gender: mode(rows.map(row => row.User_Gender)),
                location: mode(rows.map(row => row.User_Location)),
                device: mode(rows.map(row => row.Device_Type)),
                timeOfDay: mode(rows.map(row => row.Time_of_Day)),
                Session_Duration_Min: mean(rows.map(row => row.Session_Duration_Min)),
                Pages_Viewed: mean(rows.map(row => row.Pages_Viewed)),
                Previous_Purchases: mean(rows.map(row => row.Previous_Purchases)),
                User_Rating: mean(rows.map(row => row.User_Rating)),
                purchases: positiveProductIds.map(productId => ({ ...productsById.get(productId) }))
            };
        });
    }
}

export class VectorService {
    #datasetService;
    #collectionName;
    #interactionCollectionName;
    #baseUrl;
    #collectionId;
    #interactionCollectionId;
    #initialized;
    #ready;

    constructor({
        datasetService,
        collectionName = 'ecommerce_product_vectors',
        interactionCollectionName = 'ecommerce_interaction_vectors',
        baseUrl = '/chroma'
    } = {}) {
        this.#datasetService = datasetService;
        this.#collectionName = collectionName;
        this.#interactionCollectionName = interactionCollectionName;
        this.#baseUrl = baseUrl;
        this.#collectionId = null;
        this.#interactionCollectionId = null;
        this.#initialized = false;
        this.#ready = false;
    }

    async initialize() {
        if (this.#initialized) {
            return this.#ready;
        }

        this.#initialized = true;

        try {
            const response = await fetch(
                `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections`
            );
            if (!response.ok) throw new Error(`Chroma returned ${response.status}`);

            const collections = await response.json();
            const collection = collections.find(item => item.name === this.#collectionName);
            const interactionCollection = collections.find(
                item => item.name === this.#interactionCollectionName
            );
            this.#collectionId = collection?.id || null;
            this.#interactionCollectionId = interactionCollection?.id || null;
            this.#ready = Boolean(
                this.#collectionId && collection.dimension &&
                this.#interactionCollectionId && interactionCollection.dimension
            );
        } catch (error) {
            console.warn('[VectorService] Chroma vector index is unavailable; falling back to the current recommendation flow.', error);
            this.#ready = false;
        }

        return this.#ready;
    }

    async ensureIndexed() {
        await this.initialize();
        return this.#ready;
    }

    async getCandidateProductsForUser(user) {
        await this.initialize();

        if (!this.#ready || !this.#collectionId || !this.#datasetService) {
            return null;
        }

        const { products } = await this.#datasetService.getDataset();
        const purchasedIds = new Set((user?.purchases || []).map(purchase => String(purchase.id)));
        const productVectors = new Map(
            products.map(product => [String(product.id), this.#toProductVector(product)])
        );
        const queryEmbedding = this.#toUserPreferenceVector(user, products, productVectors);
        const response = await fetch(
            `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections/${this.#collectionId}/query`,
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    query_embeddings: [queryEmbedding],
                    n_results: Math.min(100, products.length),
                    include: ['metadatas']
                })
            }
        );
        if (!response.ok) throw new Error(`Chroma query returned ${response.status}`);

        const result = await response.json();
        const productIds = result.metadatas?.[0]
            ?.map(metadata => metadata?.productId)
            .filter(Boolean) || [];
        const productsById = new Map(products.map(product => [String(product.id), product]));

        return productIds
            .map(productId => productsById.get(String(productId)))
            .filter(product => product && !purchasedIds.has(String(product.id)));
    }

    async getTrainingDataset() {
        await this.initialize();

        if (!this.#ready || !this.#interactionCollectionId || !this.#datasetService) {
            return null;
        }

        const response = await fetch(
            `${this.#baseUrl}/api/v2/tenants/default_tenant/databases/default_database/collections/${this.#interactionCollectionId}/get`,
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ include: ['documents'] })
            }
        );
        if (!response.ok) throw new Error(`Chroma interaction read returned ${response.status}`);

        const result = await response.json();
        const interactions = (result.documents || []).map(document => JSON.parse(document));
        if (!interactions.length) return null;

        const dataset = await this.#datasetService.getDataset();
        return { ...dataset, interactions };
    }

    #toProductVector(product = {}) {
        return [
            product.price,
            product.graphSimilarityScore,
            product.federatedClusterId,
            product.localModelAccuracy,
            product.globalModelWeight,
            product.personalizationFactor,
            product.purchaseProbability,
            product.recommendationRate
        ].map(value => Number.isFinite(Number(value)) ? Number(value) : 0);
    }

    #toUserPreferenceVector(user = {}, products = [], productVectors = new Map()) {
        const preferredVectors = (user.purchases || [])
            .map(purchase => productVectors.get(String(purchase.id)))
            .filter(Boolean);
        const vectors = preferredVectors.length
            ? preferredVectors
            : products.map(product => this.#toProductVector(product));
        const vectorLength = 8;

        return Array.from({ length: vectorLength }, (_, index) => {
            const total = vectors.reduce((sum, vector) => sum + vector[index], 0);
            return total / (vectors.length || 1);
        });
    }
}

